/**
 * NOVIDADE - bloquear varios dias de uma vez na agenda
 *
 * O PROBLEMA
 *
 * Para fechar a agenda de uma profissional de 3 a 8, por exemplo, era
 * preciso descobrir a secao "Repeticao", escolher "Personalizado", colocar
 * "a cada 1 dia" e contar quantas ocorrencias. Funcionava, mas ninguem
 * adivinha que "repetir a cada 1 dia, 6 vezes" quer dizer "de 3 a 8".
 *
 * COMO FICOU
 *
 * Na tela de bloqueio agora tem um campo direto: "Bloquear ate o dia".
 * Escolhe o dia inicial em cima, o dia final nesse campo, e pronto - o
 * sistema cria o bloqueio em todos os dias do periodo, incluindo o
 * primeiro e o ultimo.
 *
 * Deixando o campo em branco, funciona exatamente como antes (bloqueia so
 * o dia escolhido), e a secao "Repeticao" continua disponivel para os
 * casos de repetir toda semana, quinzena ou mes. Ela some da tela quando
 * voce preenche a data final, para nao gerar confusao entre as duas
 * formas.
 *
 * Limite de seguranca: o periodo nao pode passar de 60 dias.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node bloquear-periodo-na-agenda.mjs
 *
 * E seguro rodar duas vezes: se ja estiver aplicado, ele avisa e pula.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

const ARQUIVO = "app/(app)/agenda/components/NovoAgendamentoModal.tsx";

console.log("\nNovidade - bloqueio por periodo na agenda\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: nao encontrei o arquivo do projeto:\n");
  console.error("   " + ARQUIVO + "\n");
  console.error(
    "Coloque este script na pasta raiz do projeto (a mesma que tem o package.json) e rode de novo.\n",
  );
  process.exit(1);
}

